use vstd::prelude::*;
use vstd::slice::*;

verus! {

fn solve(n: u8, k: u8, participations: Vec<u8>) -> (result: u8)
    requires
        n > 0,
        k <= 5,
        forall |i: int| 0 <= i < participations.len() ==> participations[i] <= 5,
    ensures
        result <= n,
        result <= 255,
        result * 3 <= participations.len() as u8,
    decreases participations.len(),
{
    // Take at most n elements from participations
    let limit = n as usize;
    let considered = if participations.len() > limit {
        &participations[..limit]
    } else {
        &participations[..]
    };
    
    // Count eligible participants
    let eligible_count = considered
        .iter()
        .filter(|&&sessions| 5 - sessions >= k)
        .count();
    
    // Maximum number of disjoint teams (integer division by 3)
    (eligible_count / 3) as u8
}

} // verus!